/**
 * Opens a report.
 *
 * @param reportID - The report ID to open.
 * @param personalDetails - The personal details of the participants.
 * @param parentReportAction - The parent report action if the report is a thread.
 * @param shouldCreateNewReport - Whether to create a new report if it doesn't exist.
 */
function openReport(reportID: string, personalDetails: OnyxEntry<PersonalDetailsList>, parentReportAction?: OnyxEntry<ReportAction>, shouldCreateNewReport = false) {
    const optimisticReport: OnyxUpdate[] = [];

    // If the report does not exist, we need to create it.
    if (!ReportConnection.getAllReports()?.[`${ONYXIEYS.COLLECTION.REPORT}${reportID}`]) {
        optimisticReport.push({
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXIEYS.COLLECTION.REPORT}${reportID}`,
            value: {
                reportID,
                isOptimisticReport: true,
                isLoadingReportActions: true,
            },
        });
    }

    // If we are creating a new report, we need to save the draft.
    if (shouldCreateNewReport) {
        const draft = allReportDraftComments?.[`${ONYXIEYS.COLLECTION.REPORT_DRAFT_COMMENT}${reportID}`];
        if (draft) {
            optimisticReport.push({
                onyxMethod: Onyx.METHOD.MERGE,
                key: `${ONYXIEYS.COLLECTION.REPORT_DRAFT_COMMENT}${reportID}`,
                value: draft,
            });
        }
    }

    const parameters: OpenReportParams = {
        reportID,
        shouldCreateNewReport,
    };

    API.write(WRITE_COMMANDS.OPEN_REPORT, parameters, {
        optimisticData: optimisticReport,
    });
}

/**
 * Marks a report as unread.
 *
 * @param reportID - The report ID to mark as unread.
 * @param lastReadTime - The last read time of the report.
 */
function markAsUnread(reportID: string, lastReadTime: string) {
    const report = ReportConnection.getAllReports()?.[`${ONYXIEYS.COLLECTION.REPORT}${reportID}`];

    if (!report) {
        return;
    }

    const optimisticData: OnyxUpdate[] = [
        {
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXIEYS.COLLECTION.REPORT}${reportID}`,
            value: {
                lastVisibleActionCreated: report.lastReadTime,
            },
        },
    ];

    const parameters: MarkAsUnreadParams = {
        reportID,
        lastReadTime,
    };

    API.write(WRITE_COMMANDS.MARK_AS_UNREAD, parameters, {optimisticData});
}

/**
 * Toggles a report as pinned.
 *
 * @param report - The report to toggle.
 */
function togglePinnedState(report: Report) {
    const optimisticData: OnyxUpdate[] = [
        {
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXIEYS.COLLECTION.REPORT}${report.reportID}`,
            value: {
                isPinned: !report.isPinned,
            },
        },
    ];

    const parameters: TogglePinnedChatParams = {
        reportID: report.reportID,
        isPinned: !report.isPinned,
    };

    API.write(WRITE_COMMANDS.TOGGLE_PINNED_CHAT, parameters, {optimisticData});
}
