extras.new_content:
function openReport(
    reportID: string,
    reportActionID?: string,
    participantLoginList: string[] = [],
    newReportObject?: ReportUtils.OptimisticChatReport,
    parentReportActionID = '-1',
    isFromDeepLink = false,
    participantAccountIDList: number[] = [],
    avatar?: File | CustomRNImageManipulatorResult,
) {
    if (!reportID) {
        return;
    }

    const optimisticReport: OnyxUpdate[] = [];

    // If the report does not exist, we need to create it.
    if (!ReportConnection.getAllReports()?.[`${ONYXKEYS.COLLECTION.REPORT}${reportID}`]) {
        optimisticReport.push({
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXKEYS.COLLECTION.REPORT}${reportID}`,
            value: {
                reportID,
                isOptimisticReport: true,
                isLoadingReportActions: true,
            },
        });
    }

    // If we are creating a new report, we need to save the draft.
    const draft = allReportDraftComments?.[`${ONYXKEYS.COLLECTION.REPORT_DRAFT_COMMENT}${reportID}`];
    if (draft) {
        optimisticReport.push({
            onyxMethod: Onyx.METHOD.MERGE,
            key: `${ONYXKEYS.COLLECTION.REPORT_DRAFT_COMMENT}${reportID}`,
            value: draft,
        });
    }

    const parameters: OpenReportParams = {
        reportID,
    };

    API.write(WRITE_COMMANDS.OPEN_REPORT, parameters, {
        optimisticData: optimisticReport,
    });
}

